helpers.log('Chat trigger received message');
const message = data.message || '';
const sessionId = data.sessionId || 'default';
const userId = data.userId || 'anonymous';
const timestamp = data.timestamp || new Date().toISOString();

helpers.log(`Session: ${sessionId}`);
helpers.log(`User: ${userId}`);
helpers.log(`Message: ${message}`);

// History settings
const enableHistory = node.properties.enableHistory?.value !== false;
const maxHistoryLength = parseInt(node.properties.maxHistoryLength?.value || 50);

// Merge incoming history (if any) WITHOUT appending current message (the agent añade el mensaje actual)
let history = { agent: [], user: [] };
if (enableHistory) {
  const incomingHistory = (data && data.history) || {};
  const userHist = Array.isArray(incomingHistory.user) ? incomingHistory.user : [];
  const agentHist = Array.isArray(incomingHistory.agent) ? incomingHistory.agent : [];
  const maxLen = Math.max(userHist.length, agentHist.length);
  const start = Math.max(0, maxLen - maxHistoryLength);
  history = {
    user: userHist.slice(start),
    agent: agentHist.slice(start)
  };
} else {
  helpers.log('History disabled by configuration');
}

return {
  message,
  sessionId,
  userId,
  timestamp,
  chat: {
    id: node.properties.chatId.value,
    name: node.properties.chatName.value
  },
  history,
  metadata: data.metadata || {}
};
